import {
  BarChart3,
  Briefcase,
  Building2,
  CalendarDays,
  FileBarChart2,
  FileText,
  Hand,
  LayoutDashboard,
  LogOut,
  MessageCircle,
  Settings,
  ShieldCheck,
  Users,
} from 'lucide-react';

export const ROLES = {
  EMPLOYEE: 'employee',
  MANAGER: 'manager',
  HR: 'hr_admin',
};

export const navSections = [
  {
    title: 'MAIN',
    items: [
      { label: 'Dashboard', icon: LayoutDashboard, path: '/dashboard', roles: [ROLES.EMPLOYEE, ROLES.MANAGER, ROLES.HR] },
      { label: 'Apply Leave', icon: CalendarDays, path: '/leave/apply', roles: [ROLES.EMPLOYEE, ROLES.MANAGER, ROLES.HR] },
      { label: 'My Leave', icon: FileText, path: '/leave/my', roles: [ROLES.EMPLOYEE, ROLES.MANAGER, ROLES.HR] },
      { label: 'History', icon: FileBarChart2, path: '/leave/history', roles: [ROLES.EMPLOYEE, ROLES.MANAGER, ROLES.HR] },
      { label: 'Delegations', icon: Hand, path: '/delegations', roles: [ROLES.EMPLOYEE, ROLES.MANAGER, ROLES.HR] },
      { label: 'Chat', icon: MessageCircle, path: '/chat', roles: [ROLES.EMPLOYEE, ROLES.MANAGER, ROLES.HR], badge: 'unread' },
    ],
  },
  {
    title: 'TEAM',
    items: [
      { label: 'Approvals', icon: ShieldCheck, path: '/team/approvals', roles: [ROLES.MANAGER, ROLES.HR], badge: 'pendingApprovals' },
      { label: 'Team Calendar', icon: CalendarDays, path: '/team/calendar', roles: [ROLES.MANAGER, ROLES.HR] },
      { label: 'Reports', icon: BarChart3, path: '/team/reports', roles: [ROLES.MANAGER, ROLES.HR] },
    ],
  },
  {
    title: 'HR',
    items: [
      { label: 'HR Module', icon: Briefcase, path: '/hr', roles: [ROLES.HR] },
      { label: 'HR Verification', icon: ShieldCheck, path: '/hr/verification', roles: [ROLES.HR] },
      { label: 'Compliance', icon: ShieldCheck, path: '/hr/compliance', roles: [ROLES.HR] },
      { label: 'Users', icon: Users, path: '/hr/users', roles: [ROLES.HR] },
      { label: 'Leave Types', icon: Briefcase, path: '/hr/leave-types', roles: [ROLES.HR] },
      { label: 'Departments', icon: Building2, path: '/hr/departments', roles: [ROLES.HR] },
      { label: 'Audit Log', icon: FileText, path: '/hr/audit-log', roles: [ROLES.HR] },
    ],
  },
  {
    title: 'ACCOUNT',
    items: [
      { label: 'Settings', icon: Settings, path: '/settings', roles: [ROLES.EMPLOYEE, ROLES.MANAGER, ROLES.HR] },
      { label: 'Sign out', icon: LogOut, path: '/logout', roles: [ROLES.EMPLOYEE, ROLES.MANAGER, ROLES.HR], action: 'logout' },
    ],
  },
];

export const accessibleNavSections = (role) => navSections
  .map((section) => ({ ...section, items: section.items.filter((item) => item.roles.includes(role)) }))
  .filter((section) => section.items.length > 0);
